export type ParsedClaimSlotInstruction<
  TProgram extends string = typeof REPLICATA_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    worker: TAccountMetas[0];
    experiment: TAccountMetas[1];
    claim: TAccountMetas[2];
    workerProfile: TAccountMetas[3];
    mint: TAccountMetas[4];
    vault: TAccountMetas[5];
    workerTokenAccount: TAccountMetas[6];
    tokenProgram: TAccountMetas[7];
    systemProgram: TAccountMetas[8];
  };
  data: ClaimSlotInstructionData;
};

export function parseClaimSlotInstruction<TProgram extends string, TAccountMetas extends readonly AccountMeta[]>(
  instruction: Instruction<TProgram> & InstructionWithAccounts<TAccountMetas> & InstructionWithData<ReadonlyUint8Array>
): ParsedClaimSlotInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 9) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 9,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      worker: getNextAccount(),
      experiment: getNextAccount(),
      claim: getNextAccount(),
      workerProfile: getNextAccount(),
      mint: getNextAccount(),
      vault: getNextAccount(),
      workerTokenAccount: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getClaimSlotInstructionDataDecoder().decode(instruction.data),
  };
}
